// Generated by toolbox — the React Native Skia scene.
// Do not edit by hand: change the Skia layer and export again.

import React from "react";
import {
  BlendMode,
  Canvas,
  Fill,
  Group,
  Picture,
  select,
  Skia,
  Text,
  TextAlign,
  useFont,
  useFonts,
  vec,
  type CanvasRef,
  type SkPaint,
  type SkPicture,
  type SkTypefaceFontProvider,
} from "react-native-skia";
import { useDerivedValue, type SharedValue } from "react-native-reanimated";
import { ASSET_SOURCES } from "./assets";
import { CANVAS, sampleBinds } from "./timeline";

// One paragraph of `text` in the scene font, painted with `paint`.
function textRun(fonts: SkTypefaceFontProvider, family: string, text: string, size: number, align: TextAlign, spacing: number, paint: SkPaint) {
  "worklet";
  const style = { fontFamilies: [family], fontSize: size, letterSpacing: spacing };
  return Skia.ParagraphBuilder.Make({ textAlign: align, textStyle: style }, fonts).pushStyle(style, paint).addText(text).build();
}

// A text block as toolbox lays it out: SkParagraph breaks `text` at `width`
// and places each line horizontally; with a lineHeight (NaN: SkParagraph's
// own pitch, which rounds to whole px) each line is drawn as its own run
// exactly lineHeight below the last, its baseline `offset` (NaN: the
// font's ascent + descent centred) into its line box. anchor: -1 = y is
// the first baseline, else the share of the block above y (0 top, 0.5
// middle, 1 bottom). React Native paints text with this paint, never the
// group's: color × opacity (the groups' folded in) and the inherited blend.
function makeTextPicture(
  fonts: SkTypefaceFontProvider | null,
  family: string,
  text: string,
  size: number,
  align: TextAlign,
  width: number,
  spacing: number,
  lineHeight: number,
  anchor: number,
  offset: number,
  x: number,
  y: number,
  color: number[],
  opacity: number,
  blend: BlendMode
): SkPicture {
  "worklet";
  const recorder = Skia.PictureRecorder();
  if (!fonts) {
    recorder.beginRecording(Skia.XYWHRect(0, 0, 1, 1));
    return recorder.finishRecordingAsPicture();
  }
  const paint = Skia.Paint();
  paint.setColor(Skia.Color(color));
  paint.setAlphaf(color[3] * opacity);
  paint.setBlendMode(blend);
  const para = textRun(fonts, family, text, size, align, spacing, paint);
  para.layout(width);
  const lines = para.getLineMetrics();
  const n = lines.length;
  // The recording's cull rect: every line's advance, padded for ink.
  const pad = 4 * size + 64;
  let x0 = x;
  let x1 = x + 1;
  for (let i = 0; i < n; i++) {
    x0 = Math.min(x0, x + lines[i].left);
    x1 = Math.max(x1, x + lines[i].left + lines[i].width);
  }
  if (Number.isNaN(lineHeight)) {
    const h = para.getHeight();
    const top = anchor < 0 ? y - (n > 0 ? lines[0].baseline : 0) : y - anchor * h;
    const canvas = recorder.beginRecording(Skia.XYWHRect(x0 - pad, top - pad, x1 - x0 + 2 * pad, h + 2 * pad));
    para.paint(canvas, x, top);
    return recorder.finishRecordingAsPicture();
  }
  const asc = n > 0 ? lines[0].ascent : 0;
  const desc = n > 0 ? lines[0].descent : 0;
  const off = Number.isNaN(offset) ? (lineHeight - (asc + desc)) / 2 + asc : offset;
  // The first baseline, computed once (glyphs snap to a position grid).
  const first = anchor < 0 ? y : y - anchor * n * lineHeight + off;
  const canvas = recorder.beginRecording(Skia.XYWHRect(x0 - pad, first - off - pad, x1 - x0 + 2 * pad, n * Math.abs(lineHeight) + 2 * pad));
  for (let i = 0; i < n; i++) {
    const s = text.slice(lines[i].startIndex, lines[i].endExcludingWhitespaces);
    if (s.length === 0) continue;
    const line = textRun(fonts, family, s, size, TextAlign.Left, spacing, paint);
    line.layout(width);
    const own = line.getLineMetrics();
    line.paint(canvas, x + lines[i].left, first + i * lineHeight - (own.length > 0 ? own[0].baseline : 0));
  }
  return recorder.finishRecordingAsPicture();
}

export interface ToolboxSceneGroupProps {
  // Seconds on the toolbox timeline (see useToolboxClock).
  time: SharedValue<number>;
  // The size to draw at, in points; the scene is authored at CANVAS px.
  width: number;
  height: number;
}

export interface ToolboxSceneProps extends ToolboxSceneGroupProps {
  canvasRef?: React.Ref<CanvasRef>;
}

// The scene as one Group, scaled from toolbox canvas px to width × height:
// drop it into your own <Canvas> to stack it with other content.
export function ToolboxSceneGroup({ time, width, height }: ToolboxSceneGroupProps) {
  const B = useDerivedValue(() => sampleBinds(time.value));
  const FONTS0 = useFonts({ "geist": [ASSET_SOURCES["geist"]] });
  const D1 = useDerivedValue((): SkPicture => makeTextPicture(FONTS0, "geist", "Skia layers ship text as code: SkParagraph breaks the lines, toolbox places them.", B.value.b19, TextAlign.Left, 409.6, 0, B.value.b25, 0, B.value.b26, 51.19999999999999, 30.72, [0.6274509803921569, 0.9058823529411765, 0.8980392156862745, 1], Math.min(1, Math.max(0, Math.min(1, Math.max(0, Math.min(1, Math.max(0, 1 * 1)) * 1)) * 1)), BlendMode.SrcOver));
  const FONTS2 = useFonts({ "inter": [ASSET_SOURCES["inter"]] });
  const D3 = useDerivedValue((): SkPicture => makeTextPicture(FONTS2, "inter", "Anchored\nand spaced", 44, TextAlign.Center, 32768, 3, 48.400000000000006, 0.5, 37.434375, -16129.5, B.value.b31, [1, 0.8196078431372549, 0.4, 1], Math.min(1, Math.max(0, Math.min(1, Math.max(0, Math.min(1, Math.max(0, 1 * 1)) * 1)) * 1)), BlendMode.SrcOver));
  const FONT4 = useFont(ASSET_SOURCES["geist"], 20);
  return (
    <Group transform={[{ scaleX: width / CANVAS.width }, { scaleY: height / CANVAS.height }]}>
      <Group
        transform={[{ translateX: 0 }, { translateY: 0 }, { rotate: 0 }, { scaleX: 1 }, { scaleY: 1 }]}
        origin={vec(0, 0)}
        opacity={1}
      >
        <Group
          transform={[{ translateX: 0 }, { translateY: 0 }, { rotate: 0 }, { scaleX: 1 }, { scaleY: 1 }]}
          origin={vec(0, 0)}
          opacity={1}
        >
          <Fill color={[0.0784313725490196, 0.12941176470588237, 0.23921568627450981, 1]} opacity={1} />
          <Picture picture={D1} />
          <Picture picture={D3} />
          <Group
            transform={[{ translateX: 0 }, { translateY: 0 }, { rotate: 0 }, { scaleX: 1 }, { scaleY: 1 }]}
            origin={vec(0, 0)}
            opacity={0.85}
            blendMode="difference"
          >
            <Picture picture={makeTextPicture(FONTS0, "geist", "Blend", 132, TextAlign.Right, 32768, 0, 158.4, 1, 115.246875, -32271.36, 491.52, [1, 0.5411764705882353, 0.23921568627450981, 1], Math.min(1, Math.max(0, Math.min(1, Math.max(0, Math.min(1, Math.max(0, Math.min(1, Math.max(0, 1 * 1)) * 1)) * 0.85)) * 1)), BlendMode.Difference)} />
          </Group>
        </Group>
        <Text
          font={FONT4}
          text={"simple <Text> run"}
          x={20.48}
          y={495.22875}
          color={[1, 1, 1, 1]}
          opacity={1}
          antiAlias
        />
      </Group>
    </Group>
  );
}

export function ToolboxScene({ time, width, height, canvasRef }: ToolboxSceneProps) {
  return (
    <Canvas ref={canvasRef} style={{ width, height }}>
      <ToolboxSceneGroup time={time} width={width} height={height} />
    </Canvas>
  );
}

